        char json[1024] = { 0 };

        snprintf(key, sizeof(key), "%s%d", CFG_KEY_BACKEND_PREFIX, i);
        if (claw_config_get(key, json, sizeof(json)) != 0 || json[0] == '\0') {
            continue;
        }

        cJSON* obj = cJSON_Parse(json);
        if (!obj) {
            continue;
        }

        llm_backend_t* b = &s_backends[i];
        memset(b, 0, sizeof(*b));

